-- ============================================================================
-- Carga de la bitácora de L1Pet LV desde el registro EV-RG-SGI-54 (2026, corte 10-11-2026)
-- 879 detenciones, 28744 min, 178 días.
-- Validado contra el informe PDF: minutos por mes ene-oct idénticos; diferencias por categoría
-- menores a 0,2% (criterio de 2 eventos sin tipo). Descartadas 2 filas sin minutos (filas 681, 813).
-- Paso 1 (ALTER) no destructivo. Paso 2 se detiene si la carga ya existe (carga_id).
-- Reversión: UPDATE mrp_eventos_linea SET anulado=TRUE, anulado_por='reversion carga', anulado_en=now()
--            WHERE carga_id='EV-RG-SGI-54_2026-11-10';
-- Ejecutar: docker exec -i traverso_mrp_db psql -U mrp_user -d mrp -v ON_ERROR_STOP=1 < forecast/carga_bitacora_L1PetLV_EV-RG-SGI-54.sql
-- ============================================================================
BEGIN;

ALTER TABLE mrp_eventos_linea ADD COLUMN IF NOT EXISTS maquina          VARCHAR(60);
ALTER TABLE mrp_eventos_linea ADD COLUMN IF NOT EXISTS hora_inicio      TIME;
ALTER TABLE mrp_eventos_linea ADD COLUMN IF NOT EXISTS hora_fin         TIME;
ALTER TABLE mrp_eventos_linea ADD COLUMN IF NOT EXISTS origen_detencion VARCHAR(40);
ALTER TABLE mrp_eventos_linea ADD COLUMN IF NOT EXISTS carga_id         VARCHAR(60);
CREATE INDEX IF NOT EXISTS ix_eventos_linea_carga ON mrp_eventos_linea (carga_id);

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM mrp_eventos_linea WHERE carga_id = 'EV-RG-SGI-54_2026-11-10') THEN
    RAISE EXCEPTION 'La carga EV-RG-SGI-54_2026-11-10 ya existe: no se vuelve a insertar.';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM mrp_lineas WHERE codigo = 'L1Pet LV' AND activa) THEN
    RAISE EXCEPTION 'La línea L1Pet LV no existe o no está activa.';
  END IF;
END $$;


-- Validación: debe dar 879 eventos y 28744 min
SELECT COUNT(*) AS eventos, SUM(duracion_min) AS minutos, COUNT(DISTINCT fecha) AS dias
FROM mrp_eventos_linea WHERE carga_id = 'EV-RG-SGI-54_2026-11-10';

COMMIT;

-- Resumen por mes y tipo (fuera de la transacción, solo lectura)
SELECT to_char(fecha,'YYYY-MM') AS mes, COUNT(*) AS eventos, SUM(duracion_min) AS minutos, COUNT(DISTINCT fecha) AS dias
FROM mrp_eventos_linea WHERE carga_id = 'EV-RG-SGI-54_2026-11-10' GROUP BY 1 ORDER BY 1;
SELECT tipo, COUNT(*) AS eventos, SUM(duracion_min) AS minutos
FROM mrp_eventos_linea WHERE carga_id = 'EV-RG-SGI-54_2026-11-10' GROUP BY 1 ORDER BY 3 DESC;
